// Level definitions for three stages

export const GROUND_Y = 570;

const LEVELS = [
    {
        name: 'Farmyard',
        description: 'Escape through the farmyard - watch for fences and hay bales',
        background: '#8B4513',
        stage: 0,
        hazards: [],
        obstacles: [
            { type: 'fence', x: 200, y: 0 },
