let ovens = [];
let corn = [];

function resetHazards() {
    knives = [];
    ovens = [];
    corn = [];
}

function spawnKnife(x, y, speed, telegraphTime) {
    knives.push({
        x,
        y,
        vx: speed,
        vy: 0,
        width: 8,
        height: 3,
        telegraph: telegraphTime,
        active: true,
        throwing: true
    });
    playKnifeWhoosh();
}

function updateKnives(dt) {
    for (let i = knives.length - 1; i >= 0; i--) {
        const knife = knives[i];
        if (!knife.active) continue;

        if (knife.telegraph > 0) {
            knife.telegraph -= dt;
        } else {
            knife.x += knife.vx * dt;
            knife.y += knife.vy * dt;
        }

        // Remove if far away
        if (knife.x < -100 || knife.x > 2500) {
            knives.splice(i, 1);
        }
    }
}

function spawnOven(x, y, cycleTime, burstDuration) {
    ovens.push({
        x,
        y,
        cycleTime,
        burstDuration,
        timer: 0,
        bursting: false,
        size: 30
    });
}

function updateOvens(dt) {
    for (let i = ovens.length - 1; i >= 0; i--) {
        const oven = ovens[i];
        oven.timer += dt;

        if (oven.timer >= oven.cycleTime) {
            oven.bursting = true;
            oven.burstTimer = oven.burstDuration;
            oven.timer = 0;
            playOvenRoar();
        }

        if (oven.bursting) {
            oven.burstTimer -= dt;
            if (oven.burstTimer <= 0) {
                oven.bursting = false;
                oven.timer = oven.cycleTime;
            }
        }
    }
}

